const PHASME_REFERENCE_SITES = [
  { label: "Phasmatodea.com — fiches d'élevage", value: "https://phasmatodea.com/care-sheets", note: "Site de référence internationale sur les phasmes (biologie, élevage, taxonomie)." },
  { label: "Phasmida Species File", value: "https://phasmida.speciesfile.org/", note: "Base de données taxonomique de référence pour l'ordre des Phasmatodea." },
  { label: "Arthropodia — fiches phasmes", value: "https://www.arthropodia.fr/phasmes", note: "Centre d'élevage français, fiches d'élevage par espèce." },
];

function SourcesPanel({ sources, onChange, groupe }) {
  const [form, setForm] = useState({ type: "lien", value: "", note: "" });
  const add = () => {
    if (!form.value.trim()) return;
    onChange([...sources, { ...form, id: uid("src") }]);
    setForm({ type: "lien", value: "", note: "" });
  };
  const addQuick = (site) => {
    if (sources.some((s) => s.value === site.value)) return;
    onChange([...sources, { id: uid("src"), type: "lien", value: site.value, note: site.note }]);
  };
  const remove = (id) => onChange(sources.filter((s) => s.id !== id));
  return (
    <div>
      {groupe === "phasme" && (
        <div className="quick-sources no-print">
          <span className="field-label">Sources de référence suggérées pour les phasmes</span>
          <div className="chip-row">
            {PHASME_REFERENCE_SITES.map((site) => (
              <button key={site.value} type="button" className="chip" onClick={() => addQuick(site)}>
                <Plus size={11} style={{ marginRight: 4, verticalAlign: "-2px" }} />{site.label}
              </button>
            ))}
          </div>
        </div>
      )}
      <div className="obs-form no-print">
        <div className="field-grid">
          <Field label="Type" type="select" options={[{ id: "lien", label: "Lien web" }, { id: "biblio", label: "Référence bibliographique" }, { id: "pdf", label: "Document PDF" }, { id: "fiche", label: "Fiche d'élevage externe" }]} value={form.type} onChange={(v) => setForm((f) => ({ ...f, type: v }))} />
          <Field label="Valeur (URL, titre, référence)" value={form.value} onChange={(v) => setForm((f) => ({ ...f, value: v }))} />
        </div>
        <Field label="Remarque sur la fiabilité" value={form.note} onChange={(v) => setForm((f) => ({ ...f, note: v }))} />
        <button className="btn-primary-sm" onClick={add}><Plus size={14} /> Ajouter la source</button>
      </div>
      <div className="obs-list">
        {sources.length === 0 && <div className="empty-state"><p>Aucune source externe enregistrée.</p></div>}
        {sources.map((s) => (
          <div className="obs-item" key={s.id}>
            <div className="obs-item-head">
              <span className="meta-tag">{s.type}</span>
              <button className="icon-btn-sm no-print" onClick={() => remove(s.id)}><X size={12} /></button>
            </div>
            {/^https?:\/\//i.test(s.value) ? (
              <p><a href={s.value} target="_blank" rel="noopener noreferrer" className="source-link">{s.value}</a></p>
            ) : (
              <p>{s.value}</p>
            )}
            {s.note && <p className="muted">{s.note}</p>}
          </div>
        ))}
      </div>
      <p className="muted small-note">Les informations issues de sources externes doivent être distinguées de vos observations personnelles, consignées dans l'onglet « Journal ».</p>
    </div>
  );
}

/* ============================= TERRARIUMS ============================= */

const TERRARIUM_FIELDS = [
  ["temperature", "Température"], ["hygrometrie", "Hygrométrie"],
  ["substrat", "Type de substrat"], ["eclairage", "Éclairage"], ["ventilation", "Ventilation"], ["equipements", "Équipements"],
];

// Catégories de contenants — groupement fixe (le détail des formats, lui, est entièrement géré par l'utilisateur, voir DEFAULT_TERRARIUM_FORMATS)
const CONTAINER_CATEGORIES = [
  { id: "E", label: "Exo Terra" },
  { id: "F", label: "Flexarium / Aérarium" },
  { id: "P", label: "Bac / boîte plastique aménagé" },
  { id: "B", label: "Braplast" },
  { id: "X", label: "Atypique / hors formats standards" },
];

// Formats de référence — modifiables et extensibles par l'utilisateur via « Gérer les formats », stockés dans data.terrariumFormats.
// Cette liste ne sert que de valeur de départ pour un nouveau compte ou tant que l'utilisateur n'a rien personnalisé.
const DEFAULT_TERRARIUM_FORMATS = [
  { id: "fmt-e20", nom: "Exo Terra 20×20×20 cm", code: "E20", largeur: "20", profondeur: "20", hauteur: "20", categorie: "E" },
  { id: "fmt-e20h", nom: "Exo Terra 20×20×30 cm", code: "E20H", largeur: "20", profondeur: "20", hauteur: "30", categorie: "E" },
  { id: "fmt-e30", nom: "Exo Terra 30×30×30 cm", code: "E30", largeur: "30", profondeur: "30", hauteur: "30", categorie: "E" },
  { id: "fmt-e30h", nom: "Exo Terra 30×30×45 cm", code: "E30H", largeur: "30", profondeur: "30", hauteur: "45", categorie: "E" },
  { id: "fmt-e45", nom: "Exo Terra 45×45×45 cm", code: "E45", largeur: "45", profondeur: "45", hauteur: "45", categorie: "E" },
  { id: "fmt-e45h", nom: "Exo Terra 45×45×60 cm", code: "E45H", largeur: "45", profondeur: "45", hauteur: "60", categorie: "E" },
  { id: "fmt-b19", nom: "Braplast 19×19×19 cm", code: "B19", largeur: "19", profondeur: "19", hauteur: "19", categorie: "B" },
  { id: "fmt-f30", nom: "Aérarium Taille S 30×30×30 cm", code: "F30", largeur: "30", profondeur: "30", hauteur: "30", categorie: "F" },
  { id: "fmt-f60h", nom: "Aérarium Taille L 60×60×90 cm", code: "F60H", largeur: "60", profondeur: "60", hauteur: "90", categorie: "F" },
  { id: "fmt-f50h", nom: "Aérarium X medium 50×50×96 cm", code: "F50H", largeur: "50", profondeur: "50", hauteur: "96", categorie: "F" },
];

// Retourne les formats effectifs : ceux personnalisés par l'utilisateur s'il y en a, sinon la liste de départ
function getFormats(data) {
  return data.terrariumFormats && data.terrariumFormats.length ? data.terrariumFormats : DEFAULT_TERRARIUM_FORMATS;
}
function getShelves(data) {
  return data.shelves || [];
}

// Fusionne les deux anciens champs d'origine géographique (taxo.origine + localite_origine) en une seule valeur affichée, sans rien écraser en base
function originOf(sp) {
  const a = sp.taxo?.origine?.trim();
  const b = sp.localite_origine?.trim();
  if (a && b && a !== b) return `${a} / ${b}`;
  return a || b || "";
}

// Nom d'affichage : nom scientifique + désignation de localité/souche entre guillemets (convention PSG), distincte de la sous-espèce taxonomique formelle
function displayName(sp) {
  if (!sp) return "";
  const base = sp.sci_name || "Espèce sans nom";
  return sp.localite_culture ? `${base} "${sp.localite_culture}"` : base;
}
// Version JSX : nom scientifique en italique, souche/localité entre guillemets en romain (convention taxonomique)
// Rend un nom scientifique en respectant les conventions typographiques : mots en italique,
// sauf les mentions ouvertes (sp., cf., aff.), les années et les mentions d'auteur (parenthèses ou "Nom, année") qui restent en caractères droits
function ScientificNameText({ text }) {
  if (!text) return null;
  const ROMAN_TOKENS = /^(sp\.?|cf\.?|aff\.?|var\.?|ssp\.?)$/i;
  const YEAR_LIKE = /^\(?\d{4}\)?,?;?$/;
  const AUTHOR_LIKE = /^[A-ZÀ-Ý][a-zà-ÿ'-]+,$/; // ex : "Burmeister," — nom d'auteur suivi d'une virgule
  const parts = text.split(/(\s+)/); // conserve les espaces comme parties séparées
  let inParen = false;
  return (
    <>
      {parts.map((part, i) => {
        if (/^\s+$/.test(part)) return <span key={i}>{part}</span>;
        const opensParen = part.startsWith("(");
        if (opensParen) inParen = true;
        const roman = inParen || ROMAN_TOKENS.test(part) || YEAR_LIKE.test(part) || AUTHOR_LIKE.test(part);
        const node = roman ? <span key={i}>{part}</span> : <i key={i}>{part}</i>;
        if (part.endsWith(")")) inParen = false;
        return node;
      })}
    </>
  );
}

function SpeciesName({ sp, className }) {
  if (!sp) return null;
  return (
    <span className={className}>
      <ScientificNameText text={sp.sci_name || "Espèce sans nom"} />
      {sp.localite_culture && <span className="species-locale"> "{sp.localite_culture}"</span>}
      {sp.morph_cultivar && <span className="species-locale"> ({sp.morph_cultivar})</span>}
    </span>
  );
}

// Prochaine lettre d'étagère disponible (A, B, C…)
function nextShelfLetter(shelves) {
  const used = new Set(shelves.map((s) => s.lettre));
  for (let i = 0; i < 26; i++) {
    const letter = String.fromCharCode(65 + i);
    if (!used.has(letter)) return letter;
  }
  return "";
}

// Prochain numéro de terrarium au sein d'une étagère donnée (propre à chaque étagère, indépendant du format)
function nextNumeroInShelf(terrariums, shelfId) {
  const nums = terrariums.filter((t) => t.shelf_id === shelfId).map((t) => Number(t.numero_local) || 0);
  return (nums.length ? Math.max(...nums) : 0) + 1;
}

// Code complet du terrarium : ÉTAGÈRE.NUMÉRO-FORMAT (ex : A.1-E20H) — recalculé à la volée, jamais stocké en dur
function terrariumCode(t, shelves, formats) {
  const shelf = shelves.find((s) => s.id === t.shelf_id);
  const format = formats.find((f) => f.id === t.format_id);
  const shelfPart = shelf ? shelf.lettre : "?";
  const numPart = t.numero_local || "?";
  const formatPart = format ? format.code : (t.format_libre_code || "?");
  return `${shelfPart}.${numPart}-${formatPart}`;
}

// Étiquette lisible d'un terrarium : code + espèce(s) hébergée(s) — plus utile au quotidien qu'un nom propre
function terrariumLabel(t, allSpecies, shelves, formats) {
  const noms = (allSpecies || []).filter((s) => t.species_ids?.includes(s.id)).map((s) => s.sci_name);
  const partie = noms.length ? noms.join(", ") : "Terrarium vide";
  return `${terrariumCode(t, shelves || [], formats || DEFAULT_TERRARIUM_FORMATS)} — ${partie}`;
}

function emptyTerrarium() {
  return { id: uid("ter"), shelf_id: "", numero_local: "", format_id: "",
    largeur_manuelle: "", profondeur_manuelle: "", hauteur_manuelle: "",
    species_ids: [], date_installation: todayISO(), temperature: "", hygrometrie: "", substrat: "",
    eclairage: "", ventilation: "", equipements: "", remarques: "" };
}

function emptyShelf() {
  return { id: uid("shelf"), lettre: "", nom: "" };
}

function emptyFormat() {
  return { id: uid("fmt"), nom: "", code: "", largeur: "", profondeur: "", hauteur: "", categorie: "E" };
}

